 <style type="text/css">

    .carolina-infant-table{
         
         border-collapse: collapse;
         margin: 20px auto;
         width:100%;
       
    }

    .carolina-infant-container{
        overflow-x: auto;
    }
    /*.carolina-infant-container .row-head
    {
        vertical-align: middle !important;
        transform: rotate(270deg);
        text-transform: uppercase;
        font-weight: 600;
        white-space: nowrap;
        max-width: 60px;
    }*/

    .carolina-infant-container .table td:not(.no-border), .carolina-infant-container .table th:not(.no-border)
    {
        border-collapse: collapse;
        border-top:1px solid black;
       
      
    }
    .carolina-infant-container .table th:not(.no-border)
    {
        vertical-align: top;
    }
    
    .carolina-infant-container .table td strong
    {
        text-align: left;
    }
  
    .carolina-infant-container .table-responsive {
        border: 1px solid black;
        margin-bottom: 15px;
        overflow:auto;
        width:100%;
    } 
    .carolina-infant-container .table {
        margin-bottom: 0px !important;
    } 
    .carolina-infant-container h3 {
        color: white;
        background-color: var(--theme-color);
        margin: 0px;
        padding: 15px;
    }

  /* .half-mark{
        height: 100%;
        background: linear-gradient(90deg, #51a351 50%, #FFFFFF 50%);
    }
    .full-mark{
        height: 100%;
        background: linear-gradient(90deg, #51a351 100%, #51a351 100%);
    }
*/
    
    .half-mark.green{
        height: 100%;
        background: linear-gradient(90deg, #51a351 50%, #FFFFFF 50%);
    }
    .full-mark.green{
        height: 100%;
        background: linear-gradient(90deg, #51a351 100%, #51a351 100%);
    }
    .half-mark.red{
        height: 100%;
        background: linear-gradient(90deg, #bd362f 50%, #FFFFFF 50%);
        color: #fff !important;
    }
    .full-mark.red{
        height: 100%;
        background: linear-gradient(90deg, #bd362f 100%, #bd362f 100%);
        color: #fff !important;
    }
    .half-mark.orange{
        height: 100%;
        background: linear-gradient(90deg, #fa9f1e 50%, #FFFFFF 50%);
        color: #fff !important;
    }
    .full-mark.orange{
        height: 100%;
        background: linear-gradient(90deg, #fa9f1e 100%, #fa9f1e 100%);
        color: #fff !important;
    }
    .half-mark.blue{
        height: 100%;
        background: linear-gradient(90deg, #2f96b4 50%, #FFFFFF 50%);
        color: #fff !important;
    }
    .full-mark.blue{
        height: 100%;
        background: linear-gradient(90deg, #2f96b4 100%, #2f96b4 100%);
        color: #fff !important;
    }
    .carolina-infant-container .table td[class*='second-half'] {
        position: relative;
        z-index: 0;
    }
    .carolina-infant-container .table td[class*='second-half']:after {
        position: absolute;
        top: 0px;
        right: 0px;
        content: '';
        width: 50%;
        z-index: -1;
        height: 100%;
    }
    .carolina-infant-container .table td[class*='blue-second-half']:after{
        background-color: #2f96b4;
    }
    .carolina-infant-container .table td[class*='orange-second-half']:after{
        background-color: #fa9f1e;
    }

    .carolina-infant-container .table td[class*='green-second-half']:after{
        background-color: #51a351;
    }



    .carolina-infant-table th,
    .carolina-infant-table td {
        padding: 5px 10px  !important;
        border: 1px solid black;
        text-align: center;
        vertical-align: middle;
        overflow: hidden;
        white-space: nowrap;
      }

    .vertical-text {
        writing-mode: vertical-rl;
        transform: rotate(180deg);
        text-align: center;
        vertical-align: middle;
        padding: 10px;
        white-space: nowrap; 
    }

    .carolina-infant-table th.sticky,
    .carolina-infant-table th.sticky-second {
        background-color: #f9f9f9;
        position: sticky;
        top: 0;
        z-index: 5; 
     }

    .vertical-text.sticky, 
    .sticky-second {
        position: sticky;
        background-color: #f9f9f9; 
        z-index: 2; 
    }

    .vertical-text.sticky {
        left: 0;
        top: 0; 
        z-index: 3; 
    }

    .sticky-second {
        position: sticky;
        left: 30px; 
        z-index: 2; 
    }
       
    .carolina-infant-table > thead > tr > th {
        border: 1px solid black;
        position: sticky; 
        top: 0; 
        background-color: white; 
        z-index: 10; 
    }

    /*.carolina-infant-table th.sticky,
    .carolina-infant-table td.sticky {
        position: sticky;
        left: 0;
        
        z-index: 2;

      
    }

    .carolina-infant-table th.sticky-second,
    .carolina-infant-table td.sticky-second {
        position: sticky;
        left: 20px;
        z-index: 1;
      
    }*/
   
</style>
