    function updateInfantScore(event, element, mainIndex, objectIndex,halfClick =''){
       // $('#infants_tab .total_score').text("Assessed").removeClass('label-danger').addClass('label-success');
        var cell = event.target;
        var cellRect = cell.getBoundingClientRect();
        var cellWidth = cellRect.width;
        var clickX = event.clientX - cellRect.left;


        if(halfClick  =='divide-half-mark') {
            var pattern = /^second-half/;
            if (!pattern.test($(element).attr('class'))) {
                addMarkToElement(element, mainIndex, objectIndex, 0.5,'infants','hasSecondHalf');
                
            } else {
                
                updateResultData(mainIndex, objectIndex, 0,'infants','');
            }
            return true;
        }

        if (clickX < cellWidth / 2) {

            
            if (!$(element).hasClass('half-mark')) {
                addMarkToElement(element, mainIndex, objectIndex, 0.5,'infants','');
            } else {
                $(element).removeClass('half-mark').removeClass('red').removeClass('green');
                updateResultData(mainIndex, objectIndex, 0,'infants','');
            }
          
        } else{

              if (!$(element).hasClass('full-mark')) {
                addMarkToElement(element, mainIndex, objectIndex, 1,'infants', '');
              } else {
                $(element).removeClass('full-mark').removeClass('red').removeClass('green');
                updateResultData(mainIndex, objectIndex, 0,'infants','');
              }
           
        }
    }  


