    function addMarkToElement(element, mainIndex, objectIndex, mark,type, classType){
        var class_to_add = '';
        var class_to_remove = '';
        var hasPreviousHalfClass = '';

        var visit_color = (type === 'infants' ? infant_color : preschoolers_color);

        if (classType === 'hasSecondHalf') {
       
        var class_to_add = visit_color + '-second-half';

            if (!$(element).hasClass(class_to_add)) {

                $(element).addClass(class_to_add);
                updateResultData(mainIndex, objectIndex, mark, type); 
            } else {
        
                 $(element).removeClass(class_to_add);

                 $(element).removeClass(function (index, className) {
                   return (className.match(/\b\S*second-half\S*\b/g) || []).join(' ');
                 });

                 updateResultData(mainIndex, objectIndex, 0, type); 
            }

         return true; 

        }

        if (mark == 0.5 ) {

            class_to_add = 'half-mark ' + visit_color;
            class_to_remove = 'full-mark ' + visit_color;  
        }else {
            class_to_add = 'full-mark ' + visit_color;
            class_to_remove = 'half-mark '+ visit_color;
        }

        $(element).removeClass(class_to_remove);
        $(element).addClass(class_to_add);
        updateResultData(mainIndex, objectIndex, mark, type);

         // var hasPreviousHalfMark = $(element).siblings('td').filter('.half-mark.' + visit_color).length > 0;
         // var hasPreviousFullMark = $(element).siblings('td').filter('.full-mark.' + visit_color).length > 0;

        // if (!$(element).siblings('td').hasClass('half-mark '+ visit_color) && !$(element).siblings('td').hasClass('full-mark ' + visit_color)) {
